mapper.select:
select id, deck_id, side_a, side_b
from pw_card
where deck_id = #{deckId}
  and deleted = 0

  and id != #{excludingCardId}

select id, deck_id, side_a, side_b, created_at, updated_at, deleted from pw_card where deleted = 0 and id in
#{id}
order by id asc

mapper.update:
update pw_card
set side_a = #{sideA},
    side_b = #{sideB}
where id = #{id}
  and deleted = 0

update pw_card
set deck_id = #{targetDeckId}
where id = #{id}
  and deck_id = #{sourceDeckId}
  and deleted = 0

update pw_card
set side_a = #{value}
where id = #{id}
  and deleted = 0
  and (side_a is null or side_a = '')

update pw_card
set side_b = #{value}
where id = #{id}
  and deleted = 0
  and (side_b is null or side_b = '')
